int tcp_disconnect(struct sock *sk, int flags) {
    int err = 0;

    if (sk->sk_state != TCP_CLOSE) {
        switch (sk->sk_state) {
            case TCP_LISTEN:
                tcp_stop_listen(sk);
                break;
            case TCP_SYN_SENT:
            case TCP_SYN_RECV:
                break;
            default:
                if (sk->sk_state != TCP_CLOSE_WAIT) {
                    tcp_send_reset(sk);
                }
                break;
        }

        sk->sk_state = TCP_CLOSE;
        sk->sk_state_change(sk);
    }

    tcp_purge_transmit_queue(sk);
    tcp_purge_receive_queue(sk);

    sk->sk_wmem_queued = 0;
    sk->sk_forward_alloc = 0;
    sk->sk_sndbuf = 0;

    tcp_reset_parameters(sk);

    if (sk->fastopen_cookie) {
        kfree(sk->fastopen_cookie);
        sk->fastopen_cookie = NULL;
    }

    sk->sk_err = 0;
    sk->sk_error_report(sk);

    return err;
}

int tcp_disconnect(struct sock *sk, int flags)
{
    int err = 0;

    if (sk->sk_state != TCP_CLOSE) {
        switch (sk->sk_state) {
        case TCP_LISTEN:
            tcp_stop_listening(sk);
            break;
        case TCP_SYN_SENT:
        case TCP_SYN_RECV:
            /* Send reset if needed */
            if (tcp_send_reset(sk))
                err = -1;
            break;
        }

        sk->sk_state = TCP_CLOSE;
    }

    /* Purge transmit and receive queues */
    skb_queue_purge(&sk->sk_receive_queue);
    tcp_write_queue_purge(sk);

    /* Reset TCP parameters */
    tcp_reset(sk);

    /* Clean up fastopen-related fields */
    tcp_fastopen_cleanup(sk);

    return err;
}
